import React from 'react';
import './Projects.css';

const Projects = () => {
  return (
    <section className="projects-section" id="projects">
      <div className="projects-container">

        {/* --- Phần 1: About Me (Hình cổng vòm) --- */}
        <div className="about-editorial">
          <div className="arch-image-wrapper">
            <img src="https://picsum.photos/400/500?random=1" alt="About Me" />
            <span className="star-accent">✦</span>
          </div>
          <div className="about-text">
            <h2>About Me</h2>
            <p><strong>My real name is:</strong> Vo Hung Thinh</p>
            <p><strong>I come from:</strong> Ho Chi Minh city</p>
            <p><strong>My quote for today:</strong> hihihihihahahahahahahaha</p>
          </div>
        </div>

        {/* --- Phần 2: Achievement (Các thẻ Polaroid xếp ngang) --- */}
        <div className="achievement-editorial">
          <h2>Achievement</h2>
          <div className="polaroid-row">
            
            <div className="polaroid-card">
              <img src="https://picsum.photos/300/300?random=2" alt="PES 21" />
              <p>Master of pes 21</p>
            </div>
            
            <div className="polaroid-card">
              <img src="https://picsum.photos/300/300?random=3" alt="Free fire" />
              <p>Master of free fire</p>
            </div>
            
            <div className="polaroid-card">
              <img src="https://picsum.photos/300/300?random=4" alt="Distance" />
              <p>School distance (20km)</p>
            </div>

          </div>
        </div>

      </div>
    </section>
  );
}

export default Projects;