import React from 'react';
import './Hero.css';

const Hero = () => {
  return (
    <section className="hero-modern">
      {/* 1. Nhóm ảnh xếp chồng ở giữa */}
      <div className="polaroid-stack">
        {/* Bạn có thể đổi link ảnh tĩnh, hoặc nhúng lại thẻ <Player> Lottie vào đây */}
        <img src="https://picsum.photos/300/400?random=1" alt="Pic 1" className="pic pic-left" />
        <img src="https://picsum.photos/300/400?random=2" alt="Pic 2" className="pic pic-center" />
        <img src="https://picsum.photos/300/400?random=3" alt="Pic 3" className="pic pic-right" />
      </div>

      {/* 2. Chữ khổng lồ đè lên trên */}
      <div className="giant-typography">
        <h1 className="script-text">Hung Thinh<br/>Portfolio</h1>
      </div>

      {/* 3. Thông tin góc dưới */}
      <div className="bottom-corners">
        <span>Computer Science Student</span>
        <span>2026</span>
      </div>
    </section>
  );
};

export default Hero;